// Plain browser JS (fetch); no other globals.
(function () {
// Pouch / tempered glass lots, shared by shop-admin and the branch portal (branch copy generated by
// sales-frontend/scripts/sync-shared.js as window.LotStock). Lots are bought in bulk and stocked by price
// category (e.g. tempered glass "D8" = ₹18–50) instead of as individual products. Categories live in
// SalesServer `/api/lot-categories`; a category is stocked as product code TEMPER-D8 / POUCH-D8.

const LOT_TYPES = [
  { key: "temper", label: "Tempered Glass", code: "TEMPER", icon: "🛡" },
  { key: "pouch", label: "Pouch", code: "POUCH", icon: "👝" },
];

const lotTypeOf = (key) => LOT_TYPES.find((t) => t.key === key) || null;
const isLotItem = (item) => !!(item && lotTypeOf(item.lotType));

/** "TEMPER D8" — the title printed on a lot's barcode label. */
function lotLabelTitle(item) {
  const t = lotTypeOf(item && item.lotType);
  return t ? `${t.code} ${item.lotCategory || ""}`.trim() : "";
}

const rupees = (n) => "₹" + (Math.round(Number(n) * 100) / 100).toLocaleString("en-IN");

/** "₹18 – ₹50" ('' when the category has no range, e.g. it was deleted). */
function formatPriceRange(min, max) {
  if (min == null || max == null || min === "" || max === "") return "";
  return Number(min) === Number(max) ? rupees(min) : `${rupees(min)} – ${rupees(max)}`;
}

/** Cost per piece from what was paid for the whole lot, to the paisa. */
function lotUnitCost(amount, qty) {
  const a = Number(amount);
  const q = Math.floor(Number(qty));
  if (!(a > 0) || !(q > 0)) return 0;
  return Math.round((a / q) * 100) / 100;
}

/** Starting unit price at the POS: the category's minimum price (falls back to the cost). */
function lotStartPrice(row) {
  return row && row.priceMin != null ? Number(row.priceMin) || 0 : Number(row && row.costPrice) || 0;
}

async function lotRequest(salesUrl, token, path, method, body) {
  const res = await fetch((salesUrl || "") + path, {
    method: method || "GET",
    headers: Object.assign({ Authorization: "Bearer " + token }, body ? { "Content-Type": "application/json" } : {}),
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.success === false) throw new Error(data.message || "Request failed");
  return data;
}

const fetchLotCategories = (salesUrl, token) =>
  lotRequest(salesUrl, token, "/api/lot-categories").then((d) => (Array.isArray(d.categories) ? d.categories : []));
const createLotCategory = (salesUrl, token, category) =>
  lotRequest(salesUrl, token, "/api/lot-categories", "POST", category).then((d) => d.category);
const updateLotCategory = (salesUrl, token, id, range) =>
  lotRequest(salesUrl, token, "/api/lot-categories/" + encodeURIComponent(id), "PATCH", range).then((d) => d.category);
const deleteLotCategory = (salesUrl, token, id) =>
  lotRequest(salesUrl, token, "/api/lot-categories/" + encodeURIComponent(id), "DELETE");

window.LotStock = { LOT_TYPES, lotTypeOf, isLotItem, lotLabelTitle, formatPriceRange, lotUnitCost, lotStartPrice, fetchLotCategories, createLotCategory, updateLotCategory, deleteLotCategory };
})();
